@app.route("/BenchmarkTest00033", methods=["POST"])
def BenchmarkTest00033():
    referer_value = request.headers.get('Referer', '')
    form = FormData(payload=referer_value)
    data = form.payload
    try:
        _coerced = float(data)
    except (TypeError, ValueError):
        return jsonify({'error': 'invalid number'}), 400
    processed = _coerced
    exec(str(processed))
    return jsonify({"result": "success"})

@app.route("/BenchmarkTest00040", methods=["POST"])
def BenchmarkTest00040():
    api_value = requests.get('https://api.partner.example.com/v1/profile').text
    data, _sep, _rest = str(api_value).partition('\x00')
    parsed = urlparse(data)
    if not re.fullmatch("^(api\\.prod\\.internal|cdn\\.pycdn\\.io)$", parsed.hostname or ''):
        return jsonify({'error': 'forbidden host'}), 403
    target_url = data
    s = socket.create_connection((str(target_url), 80))
    s.close()
    return jsonify({"result": "success"})

